    async fn save_tools(&self, tools: Vec<ToolRecord>) -> Result<()> {
        let mut stored = self.tools.lock().expect("mutex should not be poisoned");
        *stored = tools;
        debug!("Saved {} tools to memory", stored.len());
        Ok(())
110→    }

    async fn load_tools(&self) -> Result<Vec<ToolRecord>> {
        let tools = self.tools.lock().expect("mutex should not be poisoned");
        Ok(tools.clone())
    }

    async fn is_tools_empty(&self) -> Result<bool> {
        let tools = self.tools.lock().expect("mutex should not be poisoned");
        Ok(tools.is_empty())
120→    }

    async fn clear_tools(&self) -> Result<()> {
        let mut tools = self.tools.lock().expect("mutex should not be poisoned");
        tools.clear();
        debug!("Cleared tools from memory");
        Ok(())
    }
}

1→//! Canonical method accountability envelope, independent of domain schemas.
//! The admitted plugin still owns the schema of `result`.
use serde::{Deserialize, Serialize};
use serde_json::Value;

pub const MAX_METHOD_ARGUMENT_BYTES: usize = 1024 * 1024;
pub const MAX_METHOD_RECEIPT_BYTES: usize = 16 * 1024 * 1024;

/// An explicit backend guarantee that this unsupported request was refused
10→/// before any effect. Never construct this from a subprocess/transport error,
/// cancellation, or a failed publication. Static diagnostics exclude private
/// arguments and backend error text; authorization must precede this refusal.
#[derive(Debug, Clone, Copy, thiserror::Error)]
#[error("{code}; {message}")]
pub struct UnsupportedBeforeEffect {
    code: &'static str,
    message: &'static str,
}

20→impl UnsupportedBeforeEffect {
    pub const fn new(code: &'static str, message: &'static str) -> Self {
        Self { code, message }
    }

    pub fn code(&self) -> &'static str {
        self.code
    }
}

30→/// Public refusal produced only after the canonical owner durably records the
